/* Time-bounded challenges and cosmetic rewards, verified by the server. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=x=>JSON.parse(JSON.stringify(x));
 const kinds={badge:'Insigne',title:'Titre',frame:'Cadre de profil',decoration:'Décoration',background:'Fond de profil',effect:'Effet de carte'},difficulties={discovery:'Découverte',collector:'Collection',prestige:'Prestige'};
 let events=[],rewards=[],selection={},owner='',epoch=0,loading=false,loaded=false,busy=false,error='',root=null,chosen='',lastPhase='',clock={at:Date.now(),received:performance.now()},queued=false;
 let shelf='live',celebration=null,celebrationTimer;
 const themes={convergence:'Convergence',eclipse:'Éclipse',nocturne:'Nocturne'};
 const themeOf=e=>Object.hasOwn(themes,e.config.theme)?e.config.theme:'convergence';
 const rewardIcon=kind=>'<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true">'+({badge:'<path d="m24 4 15 9v17L24 44 9 30V13Z"/><path d="m24 13 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/>',title:'<path d="m7 14 9 8 8-13 8 13 9-8-5 22H12Z"/><path d="M13 41h22"/>',frame:'<path d="M6 17V6h11m14 0h11v11m0 14v11H31m-14 0H6V31"/><path d="M13 13h22v22H13Z"/>',decoration:'<path d="m24 4 7 13 13 7-13 7-7 13-7-13-13-7 13-7Z"/><circle cx="24" cy="24" r="5"/>',background:'<path d="M5 8h38v32H5Z"/><path d="m6 34 11-13 9 10 5-7 12 12"/><circle cx="32" cy="17" r="4"/>',effect:'<path d="m28 3-16 25h12l-3 17 16-25H25Z"/>'}[kind]||'<path d="m24 6 18 18-18 18L6 24Z"/>')+'</svg>';
 let motion=true;try{motion=localStorage.getItem('kizuna_anomaly_motion')!=='off';}catch{}document.documentElement.dataset.kanMotion=motion?'on':'off';
 const account=()=>window.KizunaAccount?.getSnapshot?.()||{},now=()=>clock.at+Math.max(0,performance.now()-clock.received),phase=e=>now()<Date.parse(e.config.starts_at)?'upcoming':now()>=Date.parse(e.config.ends_at)?'ended':'active';
 const date=v=>!v?'Non programmée':new Date(v).toLocaleString('fr-FR',{dateStyle:'medium',timeStyle:'short'});
 function accept(result){events=result.events||[];rewards=result.rewards||[];selection=result.selection||{};clock={at:Number(result.server_now)||Date.now(),received:performance.now()};loaded=true;}
 async function refresh(force=false){const a=account(),key=a.user?.id||'guest';if(a.loading||loading&&!force)return;const token=++epoch;owner=key;loading=true;error='';render();
  try{let result;if(a.user)result=await window.KizunaAccount.anomalyRequest('get');else{const c=window.KIZUNA_CONFIG;if(!c?.supabaseUrl||!c?.supabaseKey){result={events:[],rewards:[],selection:{},server_now:Date.now()};}else{const r=await fetch(c.supabaseUrl+'/rest/v1/kizuna_anomalies?select=id,config,revision,published_at&order=published_at.desc&limit=100',{headers:{apikey:c.supabaseKey},credentials:'omit',cache:'no-store'});if(!r.ok)throw Error('Les Anomalies ne sont pas accessibles pour le moment.');const rows=await r.json();result={events:rows.map(e=>({...e,config:{...e.config,challenges:e.config.challenges.map(c=>({...c,value:0,claimed:false}))}})),rewards:[],selection:{},server_now:Date.parse(r.headers?.get('date'))||Date.now()};}}
   if(token!==epoch||key!==(account().user?.id||'guest'))return;accept(result);
  }catch(e){if(token===epoch)error=e.publicMessage||e.message;}
  finally{if(token===epoch){loading=false;render();schedule();}}
 }
 function sync(){const a=account(),key=a.user?.id||'guest';if(key!==owner||a.loading){epoch++;owner=key;events=[];rewards=[];selection={};loaded=false;loading=false;busy=false;error='';chosen='';shelf='live';celebration=null;clearTimeout(celebrationTimer);render();schedule();}if(!a.loading&&!loaded&&!loading)refresh();}
 async function request(action,payload){if(busy||loading||account().loading||!account().user)return;const token=epoch,key=owner,previous=events.find(e=>e.id===payload?.event)?.config.challenges.find(c=>c.id===payload?.challenge),wasClaimed=!!previous?.claimed;busy=true;error='';render();schedule();
  try{const result=await window.KizunaAccount.anomalyRequest(action,payload);if(token!==epoch||key!==owner)return;accept(result);const received=events.find(e=>e.id===payload?.event)?.config.challenges.find(c=>c.id===payload?.challenge);
   if(action==='claim'&&previous&&!wasClaimed&&received?.claimed&&!result.replayed&&!result.result?.replayed){
    celebration={owner:key,label:received.reward.label,kind:received.reward.kind,challenge:payload.challenge,event:payload.event};clearTimeout(celebrationTimer);
    window.dispatchEvent(new CustomEvent('kizuna:reward',{detail:{owner:key,message:'Récompense d’Anomalie obtenue : '+received.reward.label}}));window.KizunaGame?.notify?.('Récompense d’Anomalie obtenue. Retrouve-la sur ton profil.');
    const shown=celebration;window.KizunaExperience?.sfx?.('reward');celebrationTimer=setTimeout(()=>{if(key===owner&&celebration===shown){celebration=null;render();}},4500);
   }}
  catch(e){if(token===epoch)error=e.publicMessage||e.message;}
  finally{if(token===epoch){busy=false;render();schedule();}}
 }
 function challenge(c,e,preview=false,index=0){
  const p=phase(e),value=Math.max(0,Number(c.value)||0),goal=Math.max(1,Number(c.goal)||1),complete=value>=goal,claimed=!!c.claimed;
  const state=claimed?'claimed':p==='ended'?'ended':p==='upcoming'?'upcoming':complete?'ready':'progress';
  const celebrated=celebration?.owner===owner&&celebration.event===e.id&&celebration.challenge===c.id;
  return `<article class="kan-challenge ${claimed?'is-claimed':''} ${celebrated?'is-celebrating':''}" data-kan-state="${state}">
   <div class="kac-contract-head"><span class="kac-contract-number" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><span class="kan-difficulty">${difficulties[c.difficulty]||'Défi'}</span><span class="kac-contract-state">${claimed?'✓ Reçu':p==='ended'?'Archivé':p==='upcoming'?'À venir':complete?'À récupérer':'En cours'}</span></div>
   <h3>${esc(c.label)}</h3><p>${esc(c.description)}</p>
   <div class="kan-reward"><span class="kac-reward-emblem" data-kind="${esc(c.reward.kind)}">${rewardIcon(c.reward.kind)}</span><div><small>${kinds[c.reward.kind]||'Récompense'}</small><strong>${esc(c.reward.label)}</strong></div></div>
   <div class="kan-count"><b>${value} <small>/ ${goal}</small></b><span>${claimed?'Récompense obtenue':p==='ended'?'Événement terminé':complete?'Objectif atteint':'Progression réelle'}</span></div><div class="kan-meter" role="progressbar" aria-label="${esc(c.label)}" aria-valuemin="0" aria-valuemax="${goal}" aria-valuenow="${Math.min(goal,value)}"><i style="width:${Math.min(100,value/goal*100)}%"></i></div>
   <button class="soft-btn" type="button" data-kan-claim="${esc(c.id)}" data-event="${esc(e.id)}" ${preview||claimed||!complete||p!=='active'||!account().user||busy||loading?'disabled':''}>${claimed?'Déjà reçu':!account().user?'Connexion requise':p==='upcoming'?'Bientôt disponible':p==='ended'?'Terminé':complete?'Réclamer la récompense':'Compléter le défi'}<span aria-hidden="true">${claimed?'✓':complete&&p==='active'?'↗':'◇'}</span></button>
  </article>`;
 }
 function eventMarkup(e,preview=false){
  const c=e.config,p=phase(e),total=c.challenges.length,done=c.challenges.filter(x=>x.claimed).length,ready=c.challenges.filter(x=>!x.claimed&&Number(x.value)>=Number(x.goal)).length,theme=themeOf(e);
  const burst=!preview&&celebration?.owner===owner&&celebration.event===e.id;
  return `<article class="kan-event" data-kan-theme="${theme}" data-kan-phase="${p}">
   <header class="kan-banner" style="--kan-art:url('assets/anomalies/${theme}.svg')">${c.image?`<img class="kan-custom-image" src="${esc(c.image)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}
    <div class="kan-banner-copy"><span class="kan-eyebrow">${preview?'APERÇU PRIVÉ · ':''}ANOMALIE / ${themes[theme]}</span><span class="kac-live-state">${p==='active'?'● En cours':p==='upcoming'?'◷ Programmée':'◇ Archives'}</span><h2 tabindex="-1" data-kan-heading>${esc(c.title)}</h2><p>${esc(c.description)}</p>
     <div class="kan-countdown"><span>${p==='upcoming'?'LE PASSAGE S’OUVRE DANS':p==='active'?'LE PASSAGE SE REFERME DANS':'CHAPITRE TERMINÉ'}</span><strong ${p!=='ended'?`data-kan-countdown="${esc(p==='upcoming'?c.starts_at:c.ends_at)}"`:''}>${p==='ended'?'Récompenses conservées':'…'}</strong></div>
     <details class="kac-event-dates"><summary>Dates de l’Anomalie</summary><div class="kan-dates">${date(c.starts_at)} → ${date(c.ends_at)}<small>Dates affichées dans ton fuseau horaire</small></div></details>
    </div><div class="kan-orbit kac-event-portal" aria-hidden="true"><i></i><i></i><b class="kac-portal-line"></b><span>${theme==='eclipse'?'◐':theme==='nocturne'?'✧':'絆'}</span><small>${themes[theme]}</small></div>
   </header>
   <div class="kan-personal"><div class="kac-progress-seal" style="--kac-complete:${total?done/total*100:0}%"><b>${done}<small> / ${total}</small></b></div><div><small>TON PARCOURS</small><strong>${done} / ${total} récompenses</strong><p>${account().user?(p==='active'&&ready?ready+' récompense'+(ready>1?'s':'')+' à récupérer.':'Chaque défi garde la trace de ta progression.'):'Connecte-toi pour participer et conserver tes récompenses.'}</p></div><span class="kac-progress-caption">${p==='ended'?'LES LIENS RESTENT':p==='upcoming'?'PRÉPARE TA COLLECTION':'ÉCRIS CE CHAPITRE'}</span></div>
   ${burst?`<div class="kac-reward-arrival" role="status"><span class="kac-reward-emblem">${rewardIcon(celebration.kind)}</span><div><small>RÉCOMPENSE OBTENUE</small><strong>${esc(celebration.label)}</strong><span>Retrouve-la dans les récompenses de ton profil.</span></div></div>`:''}
   ${Object.entries(difficulties).map(([key,title])=>{const rows=c.challenges.filter(x=>x.difficulty===key);return rows.length?`<section class="kan-category" data-kan-difficulty="${key}"><h3><span aria-hidden="true">${key==='prestige'?'✧':key==='collector'?'▤':'◇'}</span>${title}${key==='prestige'?'<small>Objectifs avancés · facultatifs</small>':''}</h3><div class="kan-challenges">${rows.map((x,i)=>challenge(x,e,preview,i)).join('')}</div></section>`:'';}).join('')}
  </article>`;
 }
 function renderInto(target){root=target;render();}
 function render(){
  if(!root?.isConnected||document.body.dataset.tab!=='adventure'||!location.hash.includes('/events'))return;
  const focus=document.activeElement,hadFocus=root.contains(focus),focusAttr=['data-kan-event','data-kan-shelf','data-kan-claim','data-kan-refresh','data-kan-boosters','data-kan-heading'].find(a=>focus?.hasAttribute?.(a)),focusValue=focusAttr?focus.getAttribute(focusAttr):'',focusId=focus?.id;
  const live=events.filter(e=>phase(e)!=='ended').sort((a,b)=>(phase(a)==='active'?0:1)-(phase(b)==='active'?0:1)||Date.parse(a.config.starts_at)-Date.parse(b.config.starts_at));
  const archives=events.filter(e=>phase(e)==='ended').sort((a,b)=>Date.parse(b.config.ends_at)-Date.parse(a.config.ends_at));
  const rows=shelf==='archive'?archives:live;if(!rows.some(e=>e.id===chosen))chosen=rows[0]?.id||'';const e=rows.find(e=>e.id===chosen);lastPhase=e?phase(e):'';
  root.innerHTML=`<div class="kan-toolbar"><div class="kac-shelves" role="group" aria-label="Période des Anomalies"><button type="button" data-kan-shelf="live" aria-pressed="${shelf==='live'}">Rendez-vous <b>${live.length}</b></button><button type="button" data-kan-shelf="archive" aria-pressed="${shelf==='archive'}">Archives <b>${archives.length}</b></button></div><div class="kac-toolbar-actions"><label class="km-motion"><input id="kanMotion" type="checkbox" ${motion?'checked':''}> Animations</label><button type="button" class="soft-btn" data-kan-refresh ${loading||busy?'disabled':''}>Actualiser</button></div></div><p class="kan-status" role="status">${esc(error||(loading?'Chargement des Anomalies…':busy?'Enregistrement…':''))}</p>`;
  if(rows.length){
   root.innerHTML+=`<nav class="kan-event-tabs ${shelf==='archive'?'kac-archive-gallery':''}" aria-label="${shelf==='archive'?'Galerie des Anomalies terminées':'Choisir une Anomalie'}">${rows.map(x=>`<button type="button" data-kan-event="${esc(x.id)}" data-kan-theme="${themeOf(x)}" aria-pressed="${x.id===chosen}">${shelf==='archive'?`<span class="kac-archive-art" style="background-image:url('assets/anomalies/${themeOf(x)}.svg')" aria-hidden="true"><i>${themeOf(x)==='eclipse'?'◐':themeOf(x)==='nocturne'?'✧':'絆'}</i></span>`:''}<span class="kac-event-tab-copy"><small>${{active:'● En cours',upcoming:'◷ Programmée',ended:'CHAPITRE TERMINÉ'}[phase(x)]}</small><strong>${esc(x.config.title)}</strong>${shelf==='archive'?`<span>${date(x.config.ends_at)}</span><b>${account().user?x.config.challenges.filter(c=>c.claimed).length+' / '+x.config.challenges.length+' récompenses obtenues':'Consulter ce chapitre'} ↗</b>`:''}</span></button>`).join('')}</nav>`+eventMarkup(e);
  }else{
   root.innerHTML+=`<div class="kan-empty"><div class="kac-quiet-portal" aria-hidden="true"><i></i><i></i><span>${shelf==='archive'?'◇':'◎'}</span></div><span class="kan-eyebrow">${shelf==='archive'?'LES CHAPITRES DE KIZUNA':'ENTRE DEUX PASSAGES'}</span><h2 tabindex="-1" data-kan-heading>${error?'Le ciel est momentanément inaccessible.':shelf==='archive'?'Les archives attendent leur premier chapitre.':'Le calme avant la prochaine Anomalie.'}</h2><p>${loading?'Les rendez-vous se chargent…':error?'Tes récompenses sont conservées. Actualise pour réessayer.':shelf==='archive'?'Aucune Anomalie terminée n’est disponible dans les archives.':'Aucune Anomalie n’est programmée actuellement. Continue à explorer les univers et à réunir tes cartes.'}</p><button type="button" class="soft-btn" data-kan-boosters>Découvrir les boosters <span aria-hidden="true">↗</span></button></div>`;
  }
  if(hadFocus){const next=focusAttr?[...root.querySelectorAll('['+focusAttr+']')].find(n=>n.getAttribute(focusAttr)===focusValue):focusId?document.getElementById(focusId):null;(next&&!next.disabled?next:root.querySelector('[data-kan-heading]'))?.focus({preventScroll:true});}
  tick();
 }
 function tick(){document.querySelectorAll('[data-kan-countdown]').forEach(n=>{if(!n.dataset.kanCountdown||!Number.isFinite(Date.parse(n.dataset.kanCountdown))){n.textContent='Dates à programmer';return;}const remaining=Math.max(0,Date.parse(n.dataset.kanCountdown)-now());if(!remaining){n.textContent='Période terminée';return;}const s=Math.floor(remaining/1000),days=Math.floor(s/86400);n.textContent=(days?days+' j · ':'')+String(Math.floor(s/3600)%24).padStart(2,'0')+' h '+String(Math.floor(s/60)%60).padStart(2,'0')+' m '+String(s%60).padStart(2,'0')+' s';});const e=events.find(x=>x.id===chosen);if(e&&phase(e)!==lastPhase){lastPhase=phase(e);render();}}
 function rewardFor(kind){const key=selection[kind];return rewards.find(x=>x.key===key&&x.reward.kind===kind)?.reward||null;}
 function decorate(){
  const profile=document.getElementById('profilePage');if(profile){let panel=document.getElementById('kanCosmetics');if(!panel){panel=document.createElement('section');panel.id='kanCosmetics';panel.className='kan-cosmetics';profile.append(panel);}const signature=JSON.stringify([owner,account().loading,busy,loading,rewards,selection]);if(panel.dataset.signature!==signature){panel.dataset.signature=signature;panel.innerHTML='<header><span class="kan-eyebrow">LES TRACES DE TES ANOMALIES</span><h2>Ta signature de collectionneur.</h2><button class="soft-btn" type="button" data-kan-open>Explorer les Anomalies</button></header>'+(!account().user||account().loading?'<p>Connecte-toi pour retrouver tes récompenses.</p>':!rewards.length?'<p>Tes récompenses apparaîtront ici après tes premiers défis.</p>':'<div class="kan-cosmetic-fields">'+Object.entries(kinds).filter(([kind])=>rewards.some(x=>x.reward.kind===kind)).map(([kind,label])=>`<label>${label}<select data-kan-equip="${kind}" ${busy||loading?'disabled':''}><option value="">Présentation habituelle</option>${rewards.filter(x=>x.reward.kind===kind).map(x=>`<option value="${esc(x.key)}" ${selection[kind]===x.key?'selected':''}>${esc(x.reward.label)}</option>`).join('')}</select></label>`).join('')+'</div><div class="kan-earned">'+rewards.map(x=>`<span data-kan-style="${esc(x.reward.style)}">✧ ${esc(x.reward.label)}</span>`).join('')+'</div>');}
   for(const kind of ['frame','background','decoration'])profile.dataset['kan'+kind[0].toUpperCase()+kind.slice(1)]=account().loading?'':rewardFor(kind)?.style||'';
   let title=document.getElementById('kanProfileTitle');const caption=[rewardFor('title')?.label,rewardFor('badge')?.label].filter(Boolean).join(' · ◈ ');if(caption&&!account().loading){if(!title){title=document.createElement('p');title.id='kanProfileTitle';panel.querySelector('header').append(title);}if(title.textContent!=='✧ '+caption)title.textContent='✧ '+caption;}else title?.remove();
  }
  const effect=account().loading?'':rewardFor('effect')?.style||'';document.querySelectorAll('#collection .tcard,#detailBackdrop .tcard').forEach(n=>n.dataset.kanEffect=effect);
 }
 function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;decorate();});}
 document.addEventListener('click',e=>{const b=e.target.closest('[data-kan-event],[data-kan-shelf],[data-kan-claim],[data-kan-refresh],[data-kan-open],[data-kan-boosters]');if(!b||b.disabled)return;if(b.hasAttribute('data-kan-shelf')){shelf=b.dataset.kanShelf==='archive'?'archive':'live';chosen='';render();}else if(b.hasAttribute('data-kan-event')){chosen=b.dataset.kanEvent;render();}else if(b.hasAttribute('data-kan-claim'))request('claim',{event:b.dataset.event,challenge:b.dataset.kanClaim});else if(b.hasAttribute('data-kan-refresh'))refresh(true);else if(b.hasAttribute('data-kan-open'))window.KizunaAdventure?.navigate('events');else window.KizunaGame?.showTab('boosts');});
 document.addEventListener('change',e=>{if(e.target.id==='kanMotion'){motion=e.target.checked;document.documentElement.dataset.kanMotion=motion?'on':'off';try{localStorage.setItem('kizuna_anomaly_motion',motion?'on':'off');}catch{}}if(e.target.matches('[data-kan-equip]'))request('equip',{kind:e.target.dataset.kanEquip,key:e.target.value});});document.addEventListener('kizuna:account-change',sync);window.addEventListener('kizuna:economy-change',()=>refresh(true));window.addEventListener('focus',()=>{if(!loading)refresh();});
 new MutationObserver(schedule).observe(document.querySelector('main'),{childList:true,subtree:true});setInterval(()=>{if(!document.hidden)tick();},1000);
 window.KizunaAnomalies={renderInto,refresh,getSnapshot:()=>({events:clone(events),rewards:clone(rewards),selection:clone(selection),loading,owner}),preview:config=>eventMarkup({id:'preview',config},true),open:()=>window.KizunaAdventure?.navigate('events')};
 const route=()=>{if(location.hash==='#anomalies')window.KizunaAdventure?.navigate('events');};window.addEventListener('hashchange',route);document.addEventListener('DOMContentLoaded',route);sync();schedule();
})();
